    return int(m.group(1)) if m else None


def norm_status(s):
    s = re.sub(r"[\s\-]+", "_", (s or "").strip().lower())
    return HARBOR_STATE.get(s, s)


def counted(status):
    return status in ("delivered", "delivered_late")


def rtype(s):
    s = (s or "").strip().lower()
    if s.startswith("v"):
        return "void"
    if s.startswith(("c", "a")):
        return "correction"
    return "new"


def parse_unit(s):
    m = re.search(r"\b(kg|g|lb|oz)s?\b", (s or "").lower())
    return m.group(1) if m else None


def parse_weight(text, unit, decimal_comma):
    """Return Decimal kg. A unit written with the value wins over `unit`."""
    t = (text or "").strip()
    m = re.fullmatch(r"([-+]?[\d.,\s]*\d)\s*([A-Za-z]+)?", t)
    if not m:
        return None
    num, u = m.group(1), m.group(2)
    if u:
        u = u.lower()
        u = {"kgs": "kg", "lbs": "lb", "gram": "g", "grams": "g"}.get(u, u)
        if u in KG:
            unit = u
    num = re.sub(r"\s", "", num)
    if decimal_comma:
        num = num.replace(".", "").replace(",", ".")
    else:
        num = num.replace(",", "")
    try:
        return Decimal(num) * KG[unit]
    except Exception:
        return None


def to_date_str(d):
    return d.strftime("%Y-%m")


def parse_date(s, form):
    """Return 'YYYY-MM' of a ship date/time (UTC)."""
    s = (s or "").strip()
    m = re.fullmatch(r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:[.,]\d+)?)?\s*(Z|[+-]\d\d(?::?\d\d)?)?", s)
    if m:
        y, mo, d, h, mi, sec, off = m.groups()
        dt = datetime(int(y), int(mo), int(d), int(h), int(mi), int(sec or 0))
        if off and off != "Z":
            sign = -1 if off[0] == "-" else 1
            digits = off[1:].replace(":", "")
            delta = timedelta(hours=int(digits[:2]), minutes=int(digits[2:] or 0))
            dt = dt - sign * delta
        return to_date_str(dt)
    m = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})", s)
    if m:
        return "%04d-%02d" % (int(m.group(3)), MONTHS[m.group(2).lower()])
    f = (form or "iso").strip().lower()
    if f == "serial" or re.fullmatch(r"\d{5}(\.\d+)?", s) and f not in ("yyyyddd", "yyyymmdd"):
        d = date(1899, 12, 31) + timedelta(days=int(float(s)))
        if d >= date(1900, 3, 1):
            d -= timedelta(days=1)  # spreadsheet leap-year bug: day 60 is fictitious
        return to_date_str(d)
    if f == "yyyyddd":
        d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
        return to_date_str(d)
    if f == "yyyymmdd":
        return "%s-%s" % (s[:4], s[4:6])
    if f == "dd.mm.yyyy":
        f = "dmy"
    parts = re.split(r"[-/.]", s)
    if len(parts) != 3:
        return None
    a, b, c = [int(p) for p in parts]
    if f in ("iso", "ymd", "yyyy-mm-dd"):
        y, mo = a, b
    elif f == "dmy" or f == "dd/mm/yyyy":
        y, mo = c, b
    elif f == "mm/dd/yyyy":
        y, mo = c, a
    else:
        y, mo = a, b
    return "%04d-%02d" % (y, mo)


# ---------------------------------------------------------------- parsers
# Each parser returns (seq, [record]); record = dict(num, type, status, kg, month)
def make(num, typ, status, kg, month):
    return dict(num=num, type=typ, status=status, kg=kg, month=month)


def split_logical_lines(text):
    """Yield (line, is_comment); quoted fields may span lines (comma format)."""
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i].rstrip("\r")
        i += 1
        if line.strip() == "":
            continue
        if line.startswith("#"):
            yield line, True
            continue
        yield line, False


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLUMNS[depot]
    colset = set(cols)
    decimal_comma = depot == "west"
    unit = BASE_UNIT[depot]
    form = BASE_DATE[depot]
    seq = None
    header = None
    recs = []
    lines = text.split("\n")
    i = 0
    quoting = delim == ","
    while i < len(lines):
        line = lines[i].rstrip("\r")
        i += 1
        if line.strip() == "":
            continue
        if line.startswith("#"):
            m = re.match(r"#\s*([^:=]+?)\s*[:=]\s*(.*)$", line)
            if m:
                name, val = m.group(1).lower(), m.group(2).strip()
                if seq is None and name.endswith("seq") and re.match(r"\d+", val):
                    seq = int(re.match(r"\d+", val).group(0))
                elif name in ("unit", "weight unit"):
                    u = parse_unit(val)
                    if u:
                        unit = u
                    if depot == "west" or "decimal" in val.lower():
                        v = val.lower()
                        if "decimal point" in v or "decimal dot" in v:
                            decimal_comma = False
                        elif "decimal comma" in v:
                            decimal_comma = True
                elif name in ("dates", "date format", "dates format", "date"):
                    form = val
            else:
                m = re.search(r"seq\s*=\s*(\d+)", line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if quoting:
            while line.count('"') % 2 == 1 and i < len(lines):
                line += "\n" + lines[i].rstrip("\r")
                i += 1
            try:
                fields = next(csv.reader([line]))
            except Exception:
                continue
        else:
            fields = line.split(delim)
        low = [f.strip().lower() for f in fields]
        if all(f in colset for f in low):
            header = low
            continue
        if header is None:
            header = cols
        row_unit = None
        if len(fields) == len(header) + 1:
            row_unit = parse_unit(fields[-1])
            fields = fields[:-1]
        if len(fields) < len(header):
            if not (fields and rtype(fields[0]) == "void"):
                # tolerate short void rows (only type and id)
                pass
            fields = fields + [""] * (len(header) - len(fields))
        row = dict(zip(header, [f.strip() for f in fields]))
        rec = delimited_record(depot, row, row_unit or unit, form, decimal_comma)
        if rec:
            recs.append(rec)
    return seq, recs


def delimited_record(depot, row, unit, form, dc):
    g = row.get
    if depot == "east":
        idv, typ, shipped, w, st = g("id"), g("type"), g("shipped"), g("gross"), g("status")
    elif depot == "harbor":
        idv, typ, shipped, w, st = g("ref"), g("rec"), g("date"), g("weight"), g("state")
    elif depot == "lakeside":
        idv, typ, shipped, w, st = g("id"), g("kind"), g("shipped"), g("gross_kg"), g("status")
        unit = "kg"
    elif depot == "river":
        idv, typ, shipped, w, st = g("ref"), g("t"), g("shipped"), g("weight"), g("status")
    else:
        idv, typ, shipped, w, st = g("id"), g("typ"), g("shipped"), g("weight"), g("status")
    num = id_number(idv)
    if num is None:
        return None
    t = rtype(typ)
    if t == "void":
        return make(num, t, None, None, None)
    return make(num, t, norm_status(st), parse_weight(w, unit, dc),
                parse_date(shipped, form) if shipped else None)


def parse_south(text):
    seq = None
    layout = None
    recs = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\f" in line or "SHIPMENT LISTING" in line:
            continue
        if line.strip() == "":
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\w+)", line)
            if m:
                layout = m.group(1).upper()
                continue
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        name = layout
        if name not in LAYOUTS or LAYOUTS[name][0] != len(line):
            cand = [n for n, (ln, _) in LAYOUTS.items() if ln == len(line)]
            if len(cand) != 1:
                continue
            name = cand[0]
        fields = {k: line[a - 1:b] for k, (a, b) in LAYOUTS[name][1].items()}
        num = id_number(fields["id"])
        if num is None:
            continue
        t = rtype(fields["type"])
        if t == "void":
            recs.append(make(num, t, None, None, None))
            continue
        w = int(fields["weight"])
        if name == "FW1":
            kg = Decimal(w) * KG["g"]
            month = parse_date(fields["shipped"], "YYYYDDD")
        elif name == "FW2":
            kg = Decimal(w) / 100
            month = parse_date(fields["shipped"], "YYYYMMDD")
        else:
            kg = Decimal(w) / 10 * KG["lb"]
            month = parse_date(fields["shipped"], "YYYYDDD")
        recs.append(make(num, t, FW_STATUS.get(fields["status"].strip().upper(), ""), kg, month))
    return seq, recs


def parse_north(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        try:
            v = json.loads(line)
        except Exception:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and "id" not in o:
                if seq is None and isinstance(o["meta"], dict) and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            num = id_number(str(o.get("id", "")))
            if num is None:
                continue
            t = rtype(o.get("kind"))
            if t == "void":
                recs.append(make(num, t, None, None, None))
                continue
            kg = None
            for k, val in o.items():
                m = re.fullmatch(r"weight(?:_(kg|g|lb|oz))?", k.lower())
                if m and val is not None:
                    u = m.group(1) or parse_unit(str(o.get("unit", o.get("weight_unit", "")))) or "kg"
                    kg = parse_weight(str(val), u, False)
                    break
            ship = o.get("shipped_at")
            recs.append(make(num, t, norm_status(o.get("status")), kg,
                             parse_date(str(ship), "iso") if ship else None))
    return seq, recs


def parse_central(raw):
    root = ET.fromstring(raw)
    seq = int(root.get("seq")) if root.get("seq") else None
    base = root.get("weight-unit") or "kg"
    recs = []
    for sh in root.iter("shipment"):
        def val(name):
            c = sh.find(name)
            if c is not None and c.text is not None:
                return c.text.strip()
            return sh.get(name)
        num = id_number(sh.get("id") or val("id") or "")
        if num is None:
            continue
        t = rtype(sh.get("type") or val("type"))
        if t == "void":
            recs.append(make(num, t, None, None, None))
            continue
        wel = sh.find("weight")
        unit = base
        w = None
        if wel is not None:
            unit = parse_unit(wel.get("unit")) or parse_unit(sh.get("weight-unit")) or base
            w = parse_weight(wel.text or "", unit, False)
        elif sh.get("weight") is not None:
            w = parse_weight(sh.get("weight"), parse_unit(sh.get("weight-unit")) or base, False)
        ship = val("shipped")
        recs.append(make(num, t, norm_status(val("status")), w,
                         parse_date(ship, "iso") if ship else None))
    return seq, recs


def parse_file(depot, path):
    raw = read_raw(path)
    if depot == "central" or raw.lstrip()[:5] in (b"<?xml", b"<expo") or \
            raw[:3] == b"\xef\xbb\xbf<" and depot == "central":
        return parse_central(raw)
    text = decode(raw)
    if depot == "south":
        return parse_south(text)
    if depot == "north":
        return parse_north(text)
    return parse_delimited(depot, text)


# ---------------------------------------------------------------- main
def main(data_dir, out_file):
    exports = {}
    for entry in sorted(os.scandir(data_dir), key=lambda e: e.name):
        if not entry.is_file():
            continue
        depot = entry.name.split("-", 1)[0]
        exports.setdefault(depot, [])
        if depot in COLUMNS or depot in ("south", "north", "central"):
            seq, recs = parse_file(depot, entry.path)
            exports[depot].append((seq if seq is not None else -1, entry.name, recs))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        cur = {}
        for seq, name, recs in sorted(files, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    rank = {d: i for i, d in enumerate(DEPOT_ORDER)}
    owners = {}
    for depot, cur in current.items():
        for n in cur:
            owners.setdefault(n, []).append(depot)
    handovers = 0
    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: rank.get(x, 99))
        r = current[d][n]
        if not counted(r["status"]) or r["kg"] is None or r["month"] is None:
            continue
        depots[d][0] += 1
        depots[d][1] += r["kg"]
        m = months.setdefault(r["month"], [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def fmt(v):
        return float(v[1].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    out = {
        "depots": {d: {"shipments": v[0], "total_kg": fmt(v)} for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": fmt(v)} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
