def compare(got):
    ref = json.loads(DIGESTS.read_text())
    salt = ref["salt"]
    agree = {s: 0 for s in ("depots", "months", "counters")}
    wrong = []
    for section, key, val in leaves(got):
        h = hashlib.sha256(f"{salt}|{key}|{val}".encode()).hexdigest()
